16	package org.springframework.samples.petclinic.model;
17	
18	/**
19	 * Computes an owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
20	 * contained in the owner's {@code customerCode}. Non-digit characters are ignored, so the
21	 * digit depends only on the numeric content of the code.
22	 */
23	public final class CheckDigit {
24	
25	    private CheckDigit() {
26	    }
27	
28	    /**
29	     * Returns the Luhn check digit over the digits of the owner's customer code, or
30	     * {@code null} when the owner is {@code null} or has no customer code assigned yet.
31	     */
32	    public static Integer forOwner(Owner owner) {
33	        if (owner == null || owner.getCustomerCode() == null) {
34	            return null;
35	        }
36	        return luhn(owner.getCustomerCode());
37	    }
38	
39	    /**
40	     * Computes the Luhn check digit (0-9) over the decimal digits contained in {@code value},
41	     * ignoring any non-digit characters.
42	     */
43	    public static int luhn(String value) {
44	        int sum = 0;
45	        boolean doubling = true;
46	        for (int i = value.length() - 1; i >= 0; i--) {
47	            char c = value.charAt(i);
48	            if (c < '0' || c > '9') {
49	                continue;
50	            }
51	            int digit = c - '0';
52	            if (doubling) {
53	                digit *= 2;
54	                if (digit > 9) {
55	                    digit -= 9;
56	                }
57	            }
58	            sum += digit;
59	            doubling = !doubling;
60	        }
61	        return (10 - (sum % 10)) % 10;
62	    }
63	}
