20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Owner identity: the single derived key that consolidates telephone, email and last name into
24	 * one value used for duplicate detection. Two owners are the same identity only when their whole
25	 * key matches; because the (normalized) telephone is part of the key, two members of one household
26	 * with different telephones have distinct identities.
27	 * <p>
28	 * The key is the SHA-256 hex digest of {@code normalizedTelephone + '|' + lowerEmail + '|' +
29	 * soundex(lastName)}, built from the owner's already-canonical fields (telephone in E.164 form,
30	 * email trimmed and lower-cased). A {@code null} field contributes an empty segment so distinct
31	 * fields cannot collide across the {@code '|'} separators.
32	 */
33	@Component
34	public class OwnerIdentity {
35	
36	    private final Soundex soundex;
37	
38	    private final Sha256 sha256;
39	
40	    public OwnerIdentity(Soundex soundex, Sha256 sha256) {
41	        this.soundex = soundex;
42	        this.sha256 = sha256;
43	    }
44	
45	    /**
46	     * The identity key for {@code owner}: the SHA-256 hex of its normalized telephone, lower-cased
47	     * email and the Soundex code of its last name.
48	     */
49	    public String key(Owner owner) {
50	        String raw = segment(owner.getTelephone())
51	            + "|" + segment(owner.getEmail())
52	            + "|" + soundex.of(owner.getLastName());
53	        return sha256.hex(raw);
54	    }
55	
56	    private String segment(String value) {
57	        return value == null ? "" : value;
58	    }
59	}
