1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.rest.controller.CityCapacityWarningEvaluator;
13	import org.springframework.samples.petclinic.rest.controller.OwnerIdentity;
14	import org.springframework.samples.petclinic.rest.controller.TelephoneFormatter;
15	import org.springframework.samples.petclinic.service.BulkSignupWarningEvaluator;
16	import org.springframework.samples.petclinic.service.MembershipLevelEvaluator;
17	
18	import java.util.Collection;
19	import java.util.List;
20	
21	/**
22	 * Maps Owner & OwnerDto using Mapstruct
23	 */
24	@Mapper(uses = PetMapper.class)
25	public abstract class OwnerMapper {
26	
27	    @Autowired
28	    protected BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
29	
30	    @Autowired
31	    protected MembershipLevelEvaluator membershipLevelEvaluator;
32	
33	    @Autowired
34	    protected CityCapacityWarningEvaluator cityCapacityWarningEvaluator;
35	
36	    @Autowired
37	    protected OwnerIdentity ownerIdentity;
38	
39	    @Autowired
40	    protected TelephoneFormatter telephoneFormatter;
41	
42	    @Mapping(target = "selfLink", expression = "java(formatSelfLink(owner))")
43	    @Mapping(target = "identityKey", expression = "java(owner == null ? null : ownerIdentity.key(owner))")
44	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
45	    @Mapping(target = "salutation", expression = "java(org.springframework.samples.petclinic.model.Salutation.forOwner(owner))")
46	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
47	    @Mapping(target = "telephoneDisplay", expression = "java(owner == null ? null : telephoneFormatter.format(owner.getTelephone()))")
48	    @Mapping(target = "fiscalYear", expression = "java(formatFiscalYear(owner))")
49	    @Mapping(target = "membershipNumber", expression = "java(org.springframework.samples.petclinic.model.MembershipNumber.forOwner(owner))")
50	    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.model.CheckDigit.forOwner(owner))")
51	    @Mapping(target = "membershipPoints", expression = "java(membershipLevelEvaluator.pointsFor(owner))")
52	    @Mapping(target = "membershipLevel", expression = "java(membershipLevelEvaluator.levelFor(owner))")
53	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
54	    @Mapping(target = "timezone", expression = "java(formatTimezone(owner))")
55	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarningEvaluator.isWarranted(owner))")
56	    @Mapping(target = "capacityWarning", expression = "java(cityCapacityWarningEvaluator.isWarranted(owner))")
57	    @Mapping(target = "contactPreference", expression = "java(org.springframework.samples.petclinic.model.ContactPreference.forOwner(owner))")
58	    @Mapping(target = "ageBand", expression = "java(org.springframework.samples.petclinic.model.AgeBand.forOwner(owner))")
59	    @Mapping(target = "ownerSegment", expression = "java(formatOwnerSegment(owner))")
60	    public abstract OwnerDto toOwnerDto(Owner owner);
61	
62	    /**
63	     * Builds an owner's canonical API path, {@code "/api/owners/<id>"}. Returns
64	     * {@code null} for a {@code null} owner or one that has not been assigned an id yet.
65	     */
66	    protected String formatSelfLink(Owner owner) {
67	        if (owner == null || owner.getId() == null) {
68	            return null;
69	        }
70	        return "/api/owners/" + owner.getId();
71	    }
72	
73	    /**
74	     * Derives an owner's fiscal year (starting 1 July) from its business-day-adjusted
75	     * registration date, formatted {@code "FY<YY>"}. Returns {@code null} for a {@code null}
76	     * owner or one whose registration date has not been assigned yet.
77	     */
78	    protected String formatFiscalYear(Owner owner) {
79	        if (owner == null || owner.getRegistrationDate() == null) {
80	            return null;
81	        }
82	        return org.springframework.samples.petclinic.model.FiscalYear
83	            .containing(owner.getRegistrationDate()).label();
84	    }
85	
86	    /**
87	     * Derives an owner's locality from its region-and-hash identity: the {@code <REGION>}
88	     * segment of the assigned {@code customerCode}. Owners without a code yet fall back to
89	     * deriving the region straight from their own fields.
90	     */
91	    protected String formatLocality(Owner owner) {
92	        if (owner == null) {
93	            return null;
94	        }
